#include "strides.h"
#include <stdio.h>
#include <string.h>
#include <time.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"OW_CHECK OSV line%d: %s\n",__LINE__,#x);return 1;}}while(0)
static int same(const OsvBook *a,const OsvBook *b){if(a->extent!=b->extent)return 0;for(unsigned i=0;i<4;++i){OsvLoan x=a->loan[i],y=b->loan[i];if(x.serial!=y.serial||x.active!=y.active||x.writer!=y.writer||x.retired!=y.retired||x.shape.offset!=y.shape.offset||x.shape.rows!=y.shape.rows||x.shape.columns!=y.shape.columns||x.shape.row_stride!=y.shape.row_stride||x.shape.column_stride!=y.shape.column_stride)return 0;}return 1;}
static int same_old(const OwBorrows *a,const OwBorrows *b){if(a->extent!=b->extent)return 0;for(unsigned i=0;i<4;++i){OwLoan x=a->loan[i],y=b->loan[i];if(x.offset!=y.offset||x.length!=y.length||x.serial!=y.serial||x.active!=y.active||x.writer!=y.writer||x.retired!=y.retired)return 0;}return 1;}
static int base(void){OwBorrows b={0};b.extent=8;OwToken t,out={99,91},children[2]={{98,90},{97,89}};CHECK(ow_borrow(&b,0,8,1,&t)==OW_OK);CHECK(ow_borrow(&b,3,1,0,&out)==OW_BUSY&&out.slot==99);for(unsigned i=0;i<3;++i)CHECK(ow_borrow(&b,8,0,1,&out)==OW_OK);OwBorrows before=b;CHECK(ow_split(&b,t,3,children)==OW_FULL&&same_old(&b,&before)&&children[0].slot==98&&children[1].serial==89);for(unsigned i=1;i<4;++i)CHECK(ow_release(&b,(OwToken){i,b.loan[i].serial})==OW_OK);CHECK(ow_split(&b,t,3,children)==OW_OK&&ow_release(&b,t)==OW_STALE);CHECK(b.loan[children[0].slot].length==3&&b.loan[children[1].slot].offset==3);OwBorrows huge={0};huge.extent=SIZE_MAX;CHECK(ow_borrow(&huge,SIZE_MAX,1,1,&out)==OW_INVALID);huge.loan[0].serial=UINT32_MAX-1;CHECK(ow_borrow(&huge,SIZE_MAX-1,1,1,&out)==OW_OK&&out.serial==UINT32_MAX);CHECK(ow_release(&huge,out)==OW_OK&&huge.loan[0].retired);puts("OSV_BASE actual-interval overlap capacity transactional-split finite-serial");return 0;}
static int strided(void){OsvBook b={0};b.extent=8;OsvToken even,odd,out={NULL,91,92};CHECK(osv_acquire(&b,(OsvShape){0,1,4,0,2},1,&even)==OW_OK);CHECK(osv_acquire(&b,(OsvShape){1,1,4,0,2},1,&odd)==OW_OK);OsvBook before=b;CHECK(osv_acquire(&b,(OsvShape){2,1,1,0,0},0,&out)==OW_BUSY&&same(&b,&before)&&out.slot==91);CHECK(osv_release(&b,even)==OW_OK&&osv_release(&b,odd)==OW_OK);OsvToken a,c;CHECK(osv_acquire(&b,(OsvShape){0,1,4,0,2},0,&a)==OW_OK&&osv_acquire(&b,(OsvShape){2,1,2,0,2},0,&c)==OW_OK);puts("OSV_STRIDED even-odd-exact-sets overlapping-readers writer-exclusion");return 0;}
static int tile(void){OsvBook b={0};b.extent=18;OsvToken parent,child[2],columns[2];CHECK(osv_acquire(&b,(OsvShape){0,3,4,6,1},1,&parent)==OW_OK);CHECK(osv_split(&b,parent,0,1,child)==OW_OK&&osv_release(&b,parent)==OW_STALE);CHECK(b.loan[child[1].slot].shape.offset==6&&b.loan[child[1].slot].shape.rows==2);CHECK(osv_split(&b,child[1],1,2,columns)==OW_OK);CHECK(b.loan[columns[1].slot].shape.offset==8&&b.loan[columns[1].slot].shape.columns==2);int32_t storage[18];for(unsigned i=0;i<18;++i)storage[i]=-99;for(size_t r=0;r<2;++r)for(size_t c=0;c<2;++c)CHECK(osv_write(&b,columns[1],storage,18,r,c,(int32_t)(10*r+c))==OW_OK);for(unsigned i=0;i<18;++i)if(i!=8&&i!=9&&i!=14&&i!=15)CHECK(storage[i]==-99);CHECK(storage[8]==0&&storage[9]==1&&storage[14]==10&&storage[15]==11);puts("OSV_TILE actual-padded-array row-column-split preserves-padding");return 0;}
static int transaction(void){OsvBook b={0};b.extent=10;OsvToken t,empty,out[2]={{NULL,91,92},{NULL,93,94}};CHECK(osv_acquire(&b,(OsvShape){0,2,2,5,1},1,&t)==OW_OK);for(unsigned i=0;i<3;++i)CHECK(osv_acquire(&b,(OsvShape){10,0,0,SIZE_MAX,SIZE_MAX},1,&empty)==OW_OK);OsvBook before=b;CHECK(osv_split(&b,t,0,1,out)==OW_FULL&&same(&b,&before)&&out[0].slot==91&&out[1].serial==94);CHECK(osv_split(&b,t,1,3,out)==OW_INVALID&&same(&b,&before));CHECK(osv_release(&b,empty)==OW_OK);CHECK(osv_split(&b,t,1,2,out)==OW_OK);CHECK(b.loan[out[1].slot].shape.columns==0);puts("OSV_TRANSACTION whole-book failure-canaries empty-padded-child");return 0;}
static int identity(void){OsvBook b={0},other={0};b.extent=4;other.extent=4;OsvToken t,next,out={NULL,91,92};b.loan[0].serial=UINT32_MAX-1;CHECK(osv_acquire(&b,(OsvShape){0,1,1,0,1},1,&t)==OW_OK&&t.serial==UINT32_MAX);CHECK(osv_release(&other,t)==OW_STALE);CHECK(osv_release(&b,t)==OW_OK&&b.loan[0].retired);CHECK(osv_acquire(&b,(OsvShape){0,1,1,0,1},1,&next)==OW_OK&&next.slot==1);OsvToken stale=next;CHECK(osv_release(&b,next)==OW_OK);CHECK(osv_acquire(&b,(OsvShape){0,1,1,0,1},1,&next)==OW_OK&&next.serial>stale.serial);CHECK(osv_release(&b,stale)==OW_STALE);for(unsigned i=0;i<4;++i){b.loan[i].active=0;b.loan[i].serial=UINT32_MAX;b.loan[i].retired=1;}CHECK(osv_acquire(&b,(OsvShape){0,0,0,0,0},0,&out)==OW_FULL&&out.slot==91);puts("OSV_IDENTITY cross-book stale-copy maximum-retirement");return 0;}
static int bounds(void){size_t indices[64],n=91;for(unsigned i=0;i<64;++i)indices[i]=92;CHECK(osv_indices(9,(OsvShape){0,2,2,1,1},indices,&n)==OW_INVALID&&n==91&&indices[0]==92);CHECK(osv_indices(SIZE_MAX,(OsvShape){SIZE_MAX-1,1,1,SIZE_MAX,SIZE_MAX},indices,&n)==OW_OK&&n==1&&indices[0]==SIZE_MAX-1);n=91;CHECK(osv_indices(SIZE_MAX,(OsvShape){1,2,1,SIZE_MAX,0},indices,&n)==OW_INVALID&&n==91);CHECK(osv_indices(SIZE_MAX,(OsvShape){0,2,2,SIZE_MAX-1,1},indices,&n)==OW_INVALID);CHECK(osv_indices(SIZE_MAX,(OsvShape){SIZE_MAX,0,64,SIZE_MAX,SIZE_MAX},indices,&n)==OW_OK&&n==0);CHECK(osv_indices(100,(OsvShape){0,9,8,8,1},indices,&n)==OW_INVALID);CHECK(osv_indices(64,(OsvShape){0,8,8,8,1},indices,&n)==OW_OK&&n==64&&indices[63]==63);puts("OSV_BOUNDS checked-width distinct-elements empty-no-arithmetic cap64");return 0;}
static int access_case(void){int32_t data[6]={1,2,3,4,5,6},out=91;OsvBook b={0};b.extent=6;OsvToken reader,writer;OsvShape s={1,2,2,3,1};CHECK(osv_acquire(&b,s,0,&reader)==OW_OK);CHECK(osv_read(&b,reader,data,6,1,1,&out)==OW_OK&&out==6);CHECK(osv_write(&b,reader,data,6,0,0,77)==OW_BUSY&&data[1]==2);out=91;CHECK(osv_read(&b,reader,data,5,0,0,&out)==OW_INVALID&&out==91);CHECK(osv_read(&b,reader,data,6,2,0,&out)==OW_INVALID&&out==91);CHECK(osv_release(&b,reader)==OW_OK&&osv_acquire(&b,s,1,&writer)==OW_OK);CHECK(osv_read(&b,reader,data,6,0,0,&out)==OW_STALE&&out==91);CHECK(osv_write(&b,writer,data,6,1,0,77)==OW_OK&&data[4]==77);puts("OSV_ACCESS actual-array checked-guard writer-authority stale-refusal");return 0;}
static int oracle(void){unsigned mode;while(scanf("%u",&mode)==1){size_t extent;OsvShape a,b;int x,y;if(mode==0){size_t off,len,off2,len2;if(scanf("%zu %zu %zu %d %zu %zu %d",&extent,&off,&len,&x,&off2,&len2,&y)!=7)return 2;OwBorrows old={0};old.extent=extent;OwToken t;OwStatus p=ow_borrow(&old,off,len,x,&t),q=ow_borrow(&old,off2,len2,y,&t);printf("%d %d\n",p,q);}else if(mode==1){if(scanf("%zu %zu %zu %zu %zu %zu",&extent,&a.offset,&a.rows,&a.columns,&a.row_stride,&a.column_stride)!=6)return 2;size_t out[64],n=91;OwStatus s=osv_indices(extent,a,out,&n);printf("%d",s);if(s==OW_OK){printf(" %zu",n);for(size_t i=0;i<n;++i)printf(" %zu",out[i]);}puts("");}else if(mode==2){if(scanf("%zu %zu %zu %zu %zu %zu %d %zu %zu %zu %zu %zu %d",&extent,&a.offset,&a.rows,&a.columns,&a.row_stride,&a.column_stride,&x,&b.offset,&b.rows,&b.columns,&b.row_stride,&b.column_stride,&y)!=13)return 2;OsvBook book={0};book.extent=extent;OsvToken t;OwStatus p=osv_acquire(&book,a,x,&t),q=osv_acquire(&book,b,y,&t);printf("%d %d\n",p,q);}else if(mode==3){unsigned axis,occupied,seed;size_t cut;if(scanf("%zu %zu %zu %zu %zu %zu %u %zu %u %u",&extent,&a.offset,&a.rows,&a.columns,&a.row_stride,&a.column_stride,&axis,&cut,&occupied,&seed)!=10)return 2;OsvBook book={0};book.extent=extent;for(unsigned i=0;i<4;++i)book.loan[i].serial=seed;OsvToken t,e,out[2];OwStatus p=osv_acquire(&book,a,1,&t);if(p!=OW_OK){printf("%d\n",p);continue;}for(unsigned i=0;i<occupied;++i)if(osv_acquire(&book,(OsvShape){extent,0,0,0,0},1,&e)!=OW_OK)return 2;OsvBook before=book;OwStatus q=osv_split(&book,t,axis,cut,out);printf("%d %d %d",p,q,q==OW_OK?osv_release(&book,t)==OW_STALE:same(&book,&before));if(q==OW_OK)for(unsigned j=0;j<2;++j){size_t idx[64],n;if(osv_indices(extent,book.loan[out[j].slot].shape,idx,&n)!=OW_OK)return 2;printf(" %zu",n);for(size_t k=0;k<n;++k)printf(" %zu",idx[k]);}puts("");}else return 2;}return ferror(stdin)?2:0;}
static int metrics(void){OsvBook b={0};b.extent=64;unsigned sum=0;double times[7];for(unsigned s=0;s<7;++s){clock_t start=clock();for(unsigned i=0;i<1000;++i){OsvToken a,c;CHECK(osv_acquire(&b,(OsvShape){0,1,32,0,2},1,&a)==OW_OK&&osv_acquire(&b,(OsvShape){1,1,32,0,2},1,&c)==OW_OK);sum+=64;CHECK(osv_release(&b,a)==OW_OK&&osv_release(&b,c)==OW_OK);}times[s]=(double)(clock()-start)/CLOCKS_PER_SEC;}printf("{\"iterations\":1000,\"checksum\":%u,\"book_size\":%zu,\"token_size\":%zu,\"allocation_calls\":0,\"seconds\":[",sum,sizeof(b),sizeof(OsvToken));for(unsigned i=0;i<7;++i)printf("%s%.9f",i?",":"",times[i]);puts("]}");return 0;}
int main(int argc,char **argv){if(argc!=2)return 2;if(!strcmp(argv[1],"strides_base"))return base();if(!strcmp(argv[1],"strides_sets"))return strided();if(!strcmp(argv[1],"strides_tile"))return tile();if(!strcmp(argv[1],"strides_transaction"))return transaction();if(!strcmp(argv[1],"strides_identity"))return identity();if(!strcmp(argv[1],"strides_bounds"))return bounds();if(!strcmp(argv[1],"strides_access"))return access_case();if(!strcmp(argv[1],"oracle"))return oracle();if(!strcmp(argv[1],"metrics"))return metrics();return 2;}
